@js:
var out = "";
var t = src.match(/<title>([\s\S]*?)<\/title>/i);
if (t) {
  var heading = t[1].replace(/<[^>]*>/g, "").replace(/\s*\|\s*TruyenQQKo\.Com\s*$/i, "").replace(/\s+Next Chap\s+\d+.*$/i, "").replace(/\s+Tiếng Việt.*$/i, "").replace(/\s+/g, " ");
  out += "<h3>" + heading + "</h3>";
}
var re = /<img\b[^>]*class="[^"]*\blazy\b[^"]*"[^>]*>/gi;
var m;
while ((m = re.exec(src)) !== null) {
  var tag = m[0];
  var u = tag.match(/data-original="([^"]+)"/i);
  if (!u) u = tag.match(/data-cdn="([^"]+)"/i);
  if (!u) u = tag.match(/src="([^"]+)"/i);
  if (!u) continue;
  var url = u[1] + "";
  if (url.indexOf("data:") === 0) continue;
  if (url.indexOf("//") === 0) url = "https:" + url;
  if (url.indexOf("/") === 0 && url.indexOf("//") !== 0) url = "https://truyenqqko.com" + url;
  url = url.replace(/&amp;/g, "&");
  url = url.replace("mangaqq.net", "i200.truyenvua.com");
  url = url.replace("cdnqq.xyz", "i200.truyenvua.com");
  url = url.replace("mangaqq.com", "i216.truyenvua.com");
  url = url.replace("photruyen.com", "i109.truyenvua.com");
  url = url.replace("tintruyen.com", "i109.truyenvua.com");
  url = url.replace("trangshop.net", "i109.truyenvua.com");
  url = url.replace("//tintruyen.net", "//i138.truyenvua.com");
  url = url.replace("//i125.tintruyen.net", "//i125.truyenvua.com");
  url = url.replace("qqtaku.com", "i125.truyenvua.com");
  out += '<p><img src="' + url + '"/></p>';
}
if (!out) out = "<p>Không tìm thấy nội dung chương.</p>";
out;
